pub fn next<G>(&mut self, graph: G) -> Option<N>
    where G: IntoNeighbors<NodeId=N>,
{
    while let Some(node) = self.stack.pop() {
        if self.discovered.visit(node) {
            for succ in graph.neighbors(node) {
